import type {TopicDeepening} from './topicDeepening';
type Local={fr:string;de:string;es:string};
const q=(prompt:string,choices:[string,string,string],correctIndex:number,explanation:string,evidence:Local)=>({prompt,choices,correctIndex,explanation,evidence});
const n=(explanation:string,first:string,second:string,difference:string,phrases:[string,string][])=>({explanation,first,second,difference,phrases:phrases.map(([text,meaning])=>({text,meaning}))});
/** Each entry is a newly written fictional scenario for one exact syllabus title. */
export const topicDeepeningFurther:readonly TopicDeepening[]=[
{id:'b1-work-responsibilities',level:'b1',section:'survival',number:9,title:'هماهنگی مسئولیت‌های کاری',passage:{
fr:'L’équipe prépare une journée portes ouvertes samedi. Léa est responsable des inscriptions : elle vérifiera la liste des visiteurs vendredi matin. Karim préparera les panneaux et les placera à l’entrée. Nadia contactera les bénévoles pour confirmer leurs horaires. Le responsable demande à chacun d’envoyer un court message quand sa tâche est terminée. Si un problème apparaît, l’équipe se réunira à quinze heures pour chercher une solution. Léa précise qu’elle ne peut pas rester après seize heures et demande à Karim de garder la liste à sa place. Karim accepte et propose de la revoir avec elle avant son départ.',
de:'Das Team bereitet für Samstag einen Tag der offenen Tür vor. Lea ist für die Anmeldungen zuständig und prüft am Freitagmorgen die Besucherliste. Karim bereitet die Schilder vor und stellt sie am Eingang auf. Nadia kontaktiert die Freiwilligen, um ihre Arbeitszeiten zu bestätigen. Der Leiter bittet alle, nach Abschluss ihrer Aufgabe eine kurze Nachricht zu schicken. Wenn ein Problem auftritt, trifft sich das Team um fünfzehn Uhr und sucht eine Lösung. Lea erklärt, dass sie nach sechzehn Uhr nicht bleiben kann, und bittet Karim, die Liste für sie aufzubewahren. Er stimmt zu und möchte die Liste vorher mit ihr durchsehen.',
es:'El equipo prepara una jornada de puertas abiertas para el sábado. Lea es responsable de las inscripciones y revisará la lista de visitantes el viernes por la mañana. Karim preparará los carteles y los colocará en la entrada. Nadia contactará con los voluntarios para confirmar sus horarios. El responsable pide a cada persona que envíe un mensaje breve cuando termine su tarea. Si surge un problema, el equipo se reunirá a las tres para buscar una solución. Lea explica que no puede quedarse después de las cuatro y pide a Karim que guarde la lista. Él acepta y propone revisarla con ella antes de que se vaya.'},
questions:[q('چه کسی فهرست بازدیدکنندگان را بررسی می‌کند؟',['لیا','نادیا','کریم'],0,'لیا مسئول ثبت‌نام و بررسی فهرست است.',{fr:'Léa est responsable des inscriptions',de:'Lea ist für die Anmeldungen zuständig',es:'Lea es responsable de las inscripciones'}),q('در صورت بروز مشکل چه زمانی جلسه برگزار می‌شود؟',['ده صبح','ساعت پانزده','ساعت شانزده'],1,'تیم ساعت پانزده جلسه می‌گذارد.',{fr:'se réunira à quinze heures',de:'trifft sich das Team um fünfzehn Uhr',es:'el equipo se reunirá a las tres'}),q('کریم دربارهٔ فهرست چه می‌پذیرد؟',['آن را حذف کند','به مدرسه بفرستد','پس از رفتن لیا آن را نگه دارد'],2,'او درخواست لیا برای نگهداری فهرست را می‌پذیرد.',{fr:'demande à Karim de garder la liste à sa place. Karim accepte',de:'bittet Karim, die Liste für sie aufzubewahren. Er stimmt zu',es:'pide a Karim que guarde la lista. Él acepta'})],
notes:{fr:n('برای تعیین مسئولیت از être responsable de و برای درخواست از demander à quelqu’un de استفاده کنید.','Léa est responsable des inscriptions.','Elle demande à Karim de garder la liste.','اولی مسئولیت و دومی درخواست انجام کار است.',[['être responsable de','مسئولِ چیزی بودن'],['confirmer un horaire','تأیید زمان‌بندی'],['terminer une tâche','پایان دادن به وظیفه']]),de:n('für etwas zuständig sein مسئولیت را مشخص می‌کند؛ bitten … zu برای درخواست انجام کار استفاده می‌شود.','Lea ist für die Anmeldungen zuständig.','Sie bittet Karim, die Liste aufzubewahren.','اولی مسئولیت و دومی درخواست انجام کار است.',[['für etwas zuständig sein','مسئولِ چیزی بودن'],['Zeiten bestätigen','تأیید زمان‌بندی'],['eine Aufgabe abschließen','پایان دادن به وظیفه']]),es:n('ser responsable de مسئولیت و pedir a alguien que + subjuntivo درخواست از فرد دیگر را بیان می‌کند.','Lea es responsable de las inscripciones.','Pide a Karim que guarde la lista.','اولی مسئولیت و دومی درخواست انجام کار است.',[['ser responsable de','مسئولِ چیزی بودن'],['confirmar horarios','تأیید زمان‌بندی'],['terminar una tarea','پایان دادن به وظیفه']])},
speaking:'در جلسه‌ای فرضی مسئولیت سه همکار و زمان تحویل را بیان کنید و برای پوشش یک محدودیت درخواست بدهید.',writing:'پیام هماهنگی بنویسید: مسئول هر کار، مهلت، مشکل احتمالی و درخواست پیگیری را مشخص کنید.',steps:['موضوع کار و زمان را معرفی کنید.','مسئول هر وظیفه را جدا بنویسید.','یک محدودیت یا مشکل احتمالی را بیان کنید.','اقدام و زمان پیگیری را مشخص کنید.'],model:{fr:'Bonjour, Léa vérifiera les inscriptions vendredi matin. Karim préparera les panneaux et Nadia confirmera les horaires des bénévoles. Merci d’envoyer un message lorsque votre tâche sera terminée. Léa ne peut pas rester après seize heures ; Karim gardera donc la liste. En cas de problème, retrouvons-nous à quinze heures pour chercher une solution.',de:'Hallo, Lea prüft am Freitagmorgen die Anmeldungen. Karim bereitet die Schilder vor und Nadia bestätigt die Zeiten der Freiwilligen. Bitte schickt eine Nachricht, wenn eure Aufgabe abgeschlossen ist. Lea kann nach sechzehn Uhr nicht bleiben, deshalb bewahrt Karim die Liste auf. Bei Problemen treffen wir uns um fünfzehn Uhr und suchen eine Lösung.',es:'Hola, Lea revisará las inscripciones el viernes por la mañana. Karim preparará los carteles y Nadia confirmará los horarios de los voluntarios. Enviad un mensaje al terminar vuestra tarea. Lea no puede quedarse después de las cuatro, así que Karim guardará la lista. Si hay un problema, nos reuniremos a las tres para buscar una solución.'}},
{id:'b1-complaint-repair',level:'b1',section:'survival',number:11,title:'درخواست رسیدگی به مشکل سفارش',passage:{
fr:'Bonjour, j’ai commandé une bouilloire sur votre site la semaine dernière. Le colis est arrivé hier, mais la poignée est cassée. Le carton ne semblait pas abîmé. J’ai conservé la facture et j’ai pris deux photos de l’objet. Je voudrais savoir si je peux obtenir un remplacement ou un remboursement. Pourriez-vous aussi m’indiquer comment renvoyer la bouilloire et qui paiera les frais de retour ? Je suis disponible par courriel et je peux envoyer les photos si nécessaire. Merci de me répondre avant vendredi, si possible.',
de:'Guten Tag, ich habe letzte Woche einen Wasserkocher auf Ihrer Website bestellt. Das Paket ist gestern angekommen, aber der Griff ist kaputt. Der Karton sah nicht beschädigt aus. Ich habe die Rechnung aufbewahrt und zwei Fotos von dem Gerät gemacht. Ich möchte wissen, ob ich einen Ersatz oder eine Rückerstattung erhalten kann. Können Sie mir auch mitteilen, wie ich den Wasserkocher zurückschicken soll und wer die Rücksendekosten bezahlt? Sie können mich per E-Mail erreichen; bei Bedarf schicke ich Ihnen die Fotos. Bitte antworten Sie mir möglichst bis Freitag. Vielen Dank.',
es:'Buenos días, la semana pasada pedí un hervidor de agua en su página web. El paquete llegó ayer, pero el asa está rota. La caja no parecía dañada. He guardado la factura y he tomado dos fotografías del producto. Quisiera saber si puedo recibir un reemplazo o un reembolso. ¿Podrían indicarme también cómo devolver el hervidor y quién pagará los gastos de devolución? Pueden contactarme por correo electrónico y puedo enviar las fotos si las necesitan. Les agradecería una respuesta antes del viernes, si es posible. Muchas gracias.'},
questions:[q('مشکل وسیله چیست؟',['رنگ آن اشتباه است','دستهٔ آن شکسته است','بسته هنوز نرسیده'],1,'گوینده می‌گوید دسته شکسته است.',{fr:'la poignée est cassée',de:'der Griff ist kaputt',es:'el asa está rota'}),q('فرستنده چه مدرکی آماده دارد؟',['فاکتور و دو عکس','گواهی تعمیر','بلیت قطار'],0,'او فاکتور را نگه داشته و دو عکس گرفته است.',{fr:'conservé la facture et j’ai pris deux photos',de:'die Rechnung aufbewahrt und zwei Fotos',es:'guardado la factura y he tomado dos fotografías'}),q('او علاوه بر راه‌حل چه اطلاعاتی می‌خواهد؟',['زمان افتتاح فروشگاه','شمارهٔ مدیر','روش بازگرداندن و هزینهٔ آن'],2,'او دربارهٔ بازگرداندن و هزینهٔ برگشت سؤال دارد.',{fr:'comment renvoyer la bouilloire et qui paiera les frais de retour',de:'wie ich den Wasserkocher zurückschicken soll und wer die Rücksendekosten bezahlt',es:'cómo devolver el hervidor y quién pagará los gastos de devolución'})],
notes:{fr:n('برای شکایت وضعیت و مدرک را جدا از درخواست توضیح دهید؛ «pourriez-vous» درخواست را مؤدبانه‌تر می‌کند.','La poignée est cassée.','Pourriez-vous m’indiquer comment retourner l’objet ?','اولی واقعیت مشاهده‌شده و دومی درخواست اطلاعات است.',[['une poignée cassée','دستهٔ شکسته'],['un remboursement','بازپرداخت'],['les frais de retour','هزینهٔ بازگرداندن']]),de:n('مشکل را مشخص کنید و با «Könnten Sie …?» یا «Können Sie …?» دربارهٔ راه‌حل و هزینه بپرسید.','Der Griff ist kaputt.','Können Sie mir sagen, wie ich das Gerät zurückschicken kann?','اولی مشکل و دومی درخواست اطلاعات است.',[['ein kaputter Griff','دستهٔ شکسته'],['eine Rückerstattung','بازپرداخت'],['die Rücksendekosten','هزینهٔ بازگرداندن']]),es:n('برای شکایت ابتدا واقعیت مشاهده‌شده را توضیح دهید و با «¿podrían…?» راه‌حل و مراحل را مؤدبانه بپرسید.','El asa está rota.','¿Podrían indicarme cómo devolver el producto?','اولی مشکل و دومی درخواست اطلاعات است.',[['un asa rota','دستهٔ شکسته'],['un reembolso','بازپرداخت'],['los gastos de devolución','هزینهٔ بازگرداندن']])},
speaking:'با پشتیبانی تماس بگیرید؛ مشکل، مدرک و راه‌حل مورد انتظار را بگویید و دربارهٔ هزینهٔ برگشت پرسش کنید.',writing:'پیامی دربارهٔ سفارش فرضی بنویسید: مشکل، مدرک، درخواست مشخص و راه تماس را بگنجانید.',steps:['کالا و زمان دریافت را معرفی کنید.','مشکل و مدارک موجود را بیان کنید.','راه‌حل و روش بازگشت را بپرسید.','لحن و زمان پاسخ را بررسی کنید.'],model:{fr:'Bonjour, la bouilloire commandée la semaine dernière est arrivée hier avec une poignée cassée. J’ai conservé la facture et pris deux photos. Pourriez-vous me dire si un remplacement ou un remboursement est possible et comment retourner le produit ? Je peux vous envoyer les photos par courriel. Merci de votre aide.',de:'Guten Tag, der letzte Woche bestellte Wasserkocher ist gestern mit einem kaputten Griff angekommen. Ich habe die Rechnung und zwei Fotos. Können Sie mir bitte sagen, ob ein Ersatz oder eine Rückerstattung möglich ist und wie ich das Gerät zurückschicken kann? Die Fotos sende ich Ihnen gern per E-Mail. Vielen Dank.',es:'Buenos días, el hervidor que pedí la semana pasada llegó ayer con el asa rota. He guardado la factura y tomado dos fotografías. ¿Podrían decirme si es posible un reemplazo o un reembolso y cómo debo devolver el producto? Puedo enviarles las fotos por correo electrónico. Muchas gracias por su ayuda.'}},
{id:'b1-relative-people',level:'b1',section:'foundation',number:19,title:'پیوند جمله‌ها با ساختار موصولی',passage:{
fr:'Maya cherche un endroit où elle pourra étudier le soir. Une amie qui habite près de la gare lui parle d’une bibliothèque de quartier. Le bâtiment que la ville a rénové possède une salle calme et une connexion gratuite. Maya rencontre un bénévole dont le travail consiste à accueillir les nouveaux visiteurs. Il lui explique comment obtenir une carte et lui montre la salle où les groupes peuvent discuter. Le vendredi, la bibliothèque ferme plus tard. Maya décide de s’inscrire et promet à son amie de lui raconter sa première visite.',
de:'Maya sucht einen Ort, an dem sie abends lernen kann. Eine Freundin, die in der Nähe des Bahnhofs wohnt, erzählt ihr von einer Stadtteilbibliothek. Das Gebäude, das die Stadt renoviert hat, besitzt einen ruhigen Raum und kostenloses Internet. Maya trifft einen Freiwilligen, dessen Aufgabe es ist, neue Besucher zu begrüßen. Er erklärt ihr, wie sie einen Ausweis bekommen kann, und zeigt ihr den Raum, in dem Gruppen diskutieren dürfen. Freitags schließt die Bibliothek später. Maya entscheidet sich für eine Anmeldung und verspricht ihrer Freundin, von ihrem ersten Besuch zu erzählen.',
es:'Maya busca un lugar donde pueda estudiar por la tarde. Una amiga que vive cerca de la estación le habla de una biblioteca del barrio. El edificio que renovó la ciudad tiene una sala tranquila y conexión gratuita. Maya conoce a un voluntario cuyo trabajo consiste en recibir a los nuevos visitantes. Él le explica cómo obtener una tarjeta y le muestra la sala donde los grupos pueden conversar. Los viernes la biblioteca cierra más tarde. Maya decide inscribirse y promete contarle a su amiga cómo fue su primera visita.'},
questions:[q('دوست مایا کجا زندگی می‌کند؟',['نزدیک ایستگاه','داخل کتابخانه','کنار فرودگاه'],0,'دوست او نزدیک ایستگاه زندگی می‌کند.',{fr:'Une amie qui habite près de la gare',de:'Eine Freundin, die in der Nähe des Bahnhofs wohnt',es:'Una amiga que vive cerca de la estación'}),q('وظیفهٔ داوطلب چیست؟',['فروش کتاب','پذیرش بازدیدکنندگان تازه','تعمیر قطار'],1,'او به بازدیدکنندگان تازه خوشامد می‌گوید.',{fr:'accueillir les nouveaux visiteurs',de:'neue Besucher zu begrüßen',es:'recibir a los nuevos visitantes'}),q('کتابخانه چه زمانی دیرتر بسته می‌شود؟',['دوشنبه','شنبه','جمعه'],2,'جمعه‌ها دیرتر بسته می‌شود.',{fr:'Le vendredi, la bibliothèque ferme plus tard',de:'Freitags schließt die Bibliothek später',es:'Los viernes la biblioteca cierra más tarde'})],
notes:{fr:n('qui برای فاعل بند موصولی، que برای مفعول، où برای مکان و dont برای رابطه با de به کار می‌رود؛ مرجع هرکدام را مشخص کنید.','L’amie qui habite près de la gare connaît la bibliothèque.','Le bâtiment que la ville a rénové est calme.','در اولی amie فاعل و در دومی bâtiment مفعول فعل بازسازی است.',[['une salle calme','اتاق آرام'],['obtenir une carte','گرفتن کارت'],['un bénévole','داوطلب']]),de:n('ضمیر موصولی با جنس و شمار مرجع و با نقش خود در بند موصولی هماهنگ می‌شود؛ فعل صرف‌شده در پایان بند می‌آید.','Die Freundin, die nahe am Bahnhof wohnt, kennt die Bibliothek.','Das Gebäude, das die Stadt renoviert hat, ist ruhig.','در اولی die فاعل و در دومی das مفعول بند موصولی است.',[['ein ruhiger Raum','اتاق آرام'],['einen Ausweis bekommen','گرفتن کارت'],['ein Freiwilliger','داوطلب']]),es:n('que برای شخص یا چیز و donde برای مکان به کار می‌رود؛ cuyo مالکیت را بیان می‌کند و با اسم پس از خود تطابق دارد.','La amiga que vive cerca conoce la biblioteca.','El edificio que renovó la ciudad es tranquilo.','در اولی amiga فاعل و در دومی edificio مفعول بند موصولی است.',[['una sala tranquila','اتاق آرام'],['obtener una tarjeta','گرفتن کارت'],['un voluntario','داوطلب']])},
speaking:'شخصی را که می‌شناسید و مکانی را که او پیشنهاد می‌کند با جمله‌های موصولی معرفی کنید.',writing:'به دوستی دربارهٔ مکان فرضی و فردی مرتبط با آن بنویسید و اطلاعات را با ساختار موصولی پیوند دهید.',steps:['مکان و دلیل انتخاب را معرفی کنید.','شخص مرتبط را معرفی کنید.','دو جملهٔ موصولی با نقش متفاوت بسازید.','مرجع و جایگاه فعل یا ضمیر را بررسی کنید.'],model:{fr:'La bibliothèque que je visite est près de la gare. Mon amie qui habite dans le quartier me l’a recommandée. J’ai rencontré un bénévole dont le travail est d’accueillir les visiteurs. Il m’a montré une salle où je peux étudier tranquillement. Je vais demander une carte et y retourner vendredi.',de:'Die Bibliothek, die ich besuche, liegt nahe am Bahnhof. Eine Freundin, die im Viertel wohnt, hat sie mir empfohlen. Ich habe einen Freiwilligen getroffen, dessen Aufgabe es ist, Besucher zu begrüßen. Er hat mir einen Raum gezeigt, in dem ich ruhig lernen kann. Ich möchte einen Ausweis beantragen und am Freitag zurückkommen.',es:'La biblioteca que visito está cerca de la estación. Una amiga que vive en el barrio me la recomendó. Conocí a un voluntario cuyo trabajo es recibir a los visitantes. Me mostró una sala donde puedo estudiar con tranquilidad. Voy a pedir una tarjeta y volveré el viernes.'}},
{id:'b1-reported-speech',level:'b1',section:'foundation',number:18,title:'بازگویی پیام همکار',passage:{
fr:'Ce matin, Nora téléphone à son collègue Sami pour lui parler de la réunion. Elle lui dit que la réunion commencera à dix heures au lieu de neuf. Elle explique que la salle habituelle est fermée et demande à Sami d’informer l’équipe du changement. Sami note le nouveau lieu : la salle vingt au premier étage. Plus tard, il écrit aux collègues que Nora a annoncé un changement d’horaire et de salle. Il précise que chacun doit apporter le rapport terminé. Avant d’envoyer le message, il rappelle Nora pour vérifier le numéro de la salle.',
de:'Heute Morgen ruft Nora ihren Kollegen Sami wegen der Besprechung an. Sie sagt ihm, dass die Besprechung um zehn statt um neun beginnt. Sie erklärt, dass der übliche Raum geschlossen ist, und bittet Sami, das Team über die Änderung zu informieren. Sami notiert den neuen Ort: Raum zwanzig im ersten Stock. Später schreibt er den Kolleginnen und Kollegen, dass Nora eine Änderung der Uhrzeit und des Raums angekündigt hat. Er ergänzt, dass alle den fertigen Bericht mitbringen sollen. Vor dem Absenden ruft er Nora noch einmal an, um die Raumnummer zu überprüfen.',
es:'Esta mañana Nora llama a su compañero Sami para hablar de la reunión. Le dice que la reunión comenzará a las diez en lugar de las nueve. Le explica que la sala habitual está cerrada y pide a Sami que informe al equipo del cambio. Sami apunta el nuevo lugar: la sala veinte en la primera planta. Más tarde escribe a sus compañeros que Nora ha anunciado un cambio de hora y de sala. Añade que cada persona debe llevar el informe terminado. Antes de enviar el mensaje, vuelve a llamar a Nora para comprobar el número de la sala.'},
questions:[q('زمان جدید جلسه چیست؟',['ساعت ده','ساعت نه','ساعت دوازده'],0,'جلسه به ساعت ده منتقل شده است.',{fr:'commencera à dix heures au lieu de neuf',de:'um zehn statt um neun beginnt',es:'comenzará a las diez en lugar de las nueve'}),q('چرا محل جلسه تغییر می‌کند؟',['گروه سفر می‌کند','سالن معمول بسته است','گزارش آماده نیست'],1,'سالن معمول بسته است.',{fr:'la salle habituelle est fermée',de:'der übliche Raum geschlossen ist',es:'la sala habitual está cerrada'}),q('سامی پیش از ارسال پیام چه می‌کند؟',['جلسه را لغو می‌کند','گزارش را حذف می‌کند','شمارهٔ سالن را با نورا بررسی می‌کند'],2,'او برای بررسی شمارهٔ سالن دوباره تماس می‌گیرد.',{fr:'rappelle Nora pour vérifier le numéro de la salle',de:'ruft er Nora noch einmal an, um die Raumnummer zu überprüfen',es:'vuelve a llamar a Nora para comprobar el número de la sala'})],
notes:{fr:n('برای بازگویی گفته می‌توان از dire que و برای درخواست از demander à quelqu’un de استفاده کرد. زمان و مرجع ضمیر را با موقعیت هماهنگ کنید.','Nora dit que la salle est fermée.','Elle demande à Sami d’informer l’équipe.','اولی گزارش اطلاعات و دومی گزارش درخواست است.',[['annoncer un changement','اعلام تغییر'],['informer l’équipe','آگاه کردن تیم'],['vérifier le numéro','بررسی شماره']]),de:n('با sagen, dass جملهٔ خبری را گزارش کنید؛ فعل بند وابسته در پایان می‌آید. bitten … zu درخواست را منتقل می‌کند.','Nora sagt, dass der Raum geschlossen ist.','Sie bittet Sami, das Team zu informieren.','اولی گزارش اطلاعات و دومی گزارش درخواست است.',[['eine Änderung ankündigen','اعلام تغییر'],['das Team informieren','آگاه کردن تیم'],['die Nummer überprüfen','بررسی شماره']]),es:n('برای گزارش گفته از decir que و برای درخواست از pedir que + subjuntivo استفاده کنید؛ گوینده و مخاطب را روشن نگه دارید.','Nora dice que la sala está cerrada.','Pide a Sami que informe al equipo.','اولی گزارش اطلاعات و دومی گزارش درخواست است.',[['anunciar un cambio','اعلام تغییر'],['informar al equipo','آگاه کردن تیم'],['comprobar el número','بررسی شماره']])},
speaking:'پیام و درخواست نورا را برای همکار غایب بازگو کنید و زمان، محل و کار لازم را روشن کنید.',writing:'پیامی به تیم بنویسید و تغییرات، منبع اطلاعات و اقدام مورد نیاز را گزارش دهید.',steps:['منبع پیام را معرفی کنید.','زمان و محل جدید را گزارش کنید.','درخواست و وسایل لازم را ذکر کنید.','شماره‌ها و ضمیرها را بررسی کنید.'],model:{fr:'Bonjour à tous, Nora m’a annoncé que la réunion commencera à dix heures au lieu de neuf, car la salle habituelle est fermée. Nous nous retrouverons dans la salle vingt au premier étage. Elle demande à chacun d’apporter le rapport terminé. J’ai vérifié le numéro de la salle avec elle. À demain !',de:'Hallo zusammen, Nora hat mir gesagt, dass die Besprechung um zehn statt um neun beginnt, weil der übliche Raum geschlossen ist. Wir treffen uns in Raum zwanzig im ersten Stock. Sie bittet alle, den fertigen Bericht mitzubringen. Ich habe die Raumnummer noch einmal mit ihr überprüft. Bis morgen!',es:'Hola a todos: Nora me ha dicho que la reunión comenzará a las diez en lugar de las nueve porque la sala habitual está cerrada. Nos reuniremos en la sala veinte de la primera planta. Ella pide que cada persona lleve el informe terminado. He comprobado el número de la sala con ella. ¡Hasta mañana!'}},
{id:'b2-negotiation',level:'b2',section:'survival',number:4,title:'مذاکره برای تغییر زمان تحویل',passage:{
fr:'Une équipe doit livrer un site internet vendredi, mais un problème technique a retardé les tests. La cliente explique qu’elle a besoin d’une version utilisable pour une présentation lundi. Le chef de projet reconnaît cette contrainte et propose de livrer vendredi les fonctions essentielles, puis les fonctions restantes mercredi. La cliente accepte cette option à condition de recevoir une liste écrite des limites avant jeudi soir. L’équipe demande aussi un interlocuteur disponible lundi pour signaler les problèmes. Avant de terminer, les deux parties résument le calendrier et conviennent de vérifier l’avancement jeudi à quinze heures. Aucun changement supplémentaire n’est accepté sans discussion.',
de:'Ein Team soll eine Website am Freitag liefern, doch ein technisches Problem hat die Tests verzögert. Die Kundin erklärt, dass sie für eine Präsentation am Montag eine nutzbare Version braucht. Der Projektleiter erkennt diese Einschränkung an und schlägt vor, am Freitag die wichtigsten Funktionen und am Mittwoch die restlichen Funktionen zu liefern. Die Kundin akzeptiert diese Möglichkeit unter der Bedingung, dass sie bis Donnerstagabend eine schriftliche Liste der Einschränkungen erhält. Das Team bittet außerdem um eine Ansprechperson, die am Montag Probleme melden kann. Vor dem Abschluss fassen beide Seiten den Zeitplan zusammen und vereinbaren, den Fortschritt am Donnerstag um fünfzehn Uhr zu prüfen. Weitere Änderungen werden nur nach Absprache akzeptiert.',
es:'Un equipo debe entregar una página web el viernes, pero un problema técnico ha retrasado las pruebas. La clienta explica que necesita una versión utilizable para una presentación el lunes. El jefe del proyecto reconoce esa condición y propone entregar el viernes las funciones esenciales y el miércoles las restantes. La clienta acepta esta opción siempre que reciba una lista escrita de las limitaciones antes del jueves por la noche. El equipo también pide una persona de contacto disponible el lunes para comunicar problemas. Antes de terminar, ambas partes resumen el calendario y acuerdan revisar el avance el jueves a las tres. No se aceptarán cambios adicionales sin una conversación previa.'},
questions:[q('مشتری برای روز دوشنبه به چه چیزی نیاز دارد؟',['نسخهٔ قابل استفاده برای ارائه','همهٔ قابلیت‌های اضافه','تعطیلی پروژه'],0,'او نسخه‌ای قابل استفاده برای ارائه نیاز دارد.',{fr:'une version utilisable pour une présentation lundi',de:'für eine Präsentation am Montag eine nutzbare Version',es:'una versión utilizable para una presentación el lunes'}),q('شرط پذیرش پیشنهاد چیست؟',['حذف همهٔ آزمون‌ها','دریافت فهرست کتبی محدودیت‌ها تا پنجشنبه شب','پرداخت هزینهٔ جدید در دوشنبه'],1,'مشتری دریافت فهرست محدودیت‌ها را شرط می‌گذارد.',{fr:'une liste écrite des limites avant jeudi soir',de:'bis Donnerstagabend eine schriftliche Liste der Einschränkungen',es:'una lista escrita de las limitaciones antes del jueves por la noche'}),q('طرفین چه زمانی پیشرفت را بررسی می‌کنند؟',['جمعه ساعت نه','دوشنبه ساعت دوازده','پنجشنبه ساعت پانزده'],2,'آنها پنجشنبه ساعت پانزده پیشرفت را بررسی می‌کنند.',{fr:'vérifier l’avancement jeudi à quinze heures',de:'den Fortschritt am Donnerstag um fünfzehn Uhr zu prüfen',es:'revisar el avance el jueves a las tres'})],
notes:{fr:n('در مذاکره ابتدا محدودیت طرف مقابل را بازگو کنید، سپس پیشنهاد مشروط بدهید. «à condition de» با مصدر و «à condition que» با subjonctif می‌آید.','Nous pouvons livrer les fonctions essentielles vendredi.','La cliente accepte à condition de recevoir une liste écrite.','اولی پیشنهاد و دومی شرط پذیرش آن است.',[['les fonctions essentielles','قابلیت‌های ضروری'],['une liste des limites','فهرست محدودیت‌ها'],['vérifier l’avancement','بررسی پیشرفت']]),de:n('در مذاکره محدودیت و پیشنهاد را روشن کنید؛ «unter der Bedingung, dass» شرط توافق را با فعل در پایان بند معرفی می‌کند.','Wir können die wichtigsten Funktionen am Freitag liefern.','Die Kundin akzeptiert unter der Bedingung, dass sie eine Liste erhält.','اولی پیشنهاد و دومی شرط پذیرش است.',[['die wichtigsten Funktionen','قابلیت‌های ضروری'],['eine Liste der Einschränkungen','فهرست محدودیت‌ها'],['den Fortschritt prüfen','بررسی پیشرفت']]),es:n('در مذاکره «siempre que» شرط را معرفی می‌کند و در این کاربرد با subjuntivo می‌آید؛ توافق را با زمان و مسئول خلاصه کنید.','Podemos entregar las funciones esenciales el viernes.','La clienta acepta siempre que reciba una lista escrita.','اولی پیشنهاد و دومی شرط پذیرش آن است.',[['las funciones esenciales','قابلیت‌های ضروری'],['una lista de limitaciones','فهرست محدودیت‌ها'],['revisar el avance','بررسی پیشرفت']])},
speaking:'نقش مدیر پروژه را بازی کنید؛ نیاز مشتری، محدودیت تیم، پیشنهاد مشروط و زمان پیگیری را در مذاکره بیان کنید.',writing:'خلاصهٔ توافقی بنویسید که تحویل مرحله‌ای، شرط مشتری، مسئول تماس و زمان بررسی را ثبت کند.',steps:['نیاز هر دو طرف را بیان کنید.','پیشنهاد و شرط را جدا بنویسید.','نقش شخص تماس و زمان را روشن کنید.','توافق و تغییرهای نیازمند مذاکره را جمع‌بندی کنید.'],model:{fr:'Nous avons convenu de livrer les fonctions essentielles vendredi et les fonctions restantes mercredi. La cliente recevra une liste écrite des limites avant jeudi soir. Elle désignera une personne disponible lundi pour signaler les problèmes. Nous vérifierons l’avancement jeudi à quinze heures. Tout changement supplémentaire devra être discuté avant d’être accepté.',de:'Wir haben vereinbart, die wichtigsten Funktionen am Freitag und die restlichen am Mittwoch zu liefern. Die Kundin erhält bis Donnerstagabend eine schriftliche Liste der Einschränkungen. Sie benennt eine Ansprechperson, die am Montag Probleme melden kann. Wir prüfen den Fortschritt am Donnerstag um fünfzehn Uhr. Weitere Änderungen müssen vor der Annahme besprochen werden.',es:'Hemos acordado entregar las funciones esenciales el viernes y las restantes el miércoles. La clienta recibirá una lista escrita de las limitaciones antes del jueves por la noche. Designará a una persona disponible el lunes para comunicar problemas. Revisaremos el avance el jueves a las tres. Cualquier cambio adicional deberá discutirse antes de aceptarse.'}},
{id:'b2-meeting-minutes',level:'b2',section:'survival',number:5,title:'جلسهٔ کاری و ثبت تصمیم',passage:{
fr:'Lors d’une réunion, l’équipe d’un musée discute de l’accueil des groupes scolaires. Sarah présente les résultats d’un questionnaire : les enseignants demandent des informations plus claires avant leur visite. Marc propose d’envoyer un document deux semaines à l’avance, mais il rappelle que l’équipe ne connaît pas encore le coût de traduction. La responsable accepte de tester le document en deux langues avec trois écoles. Sarah préparera une première version lundi et Marc demandera un devis à une traductrice. Le groupe décidera ensuite s’il faut étendre le test. Le compte rendu précise les responsables et les délais, mais ne présente pas l’extension comme une décision déjà prise.',
de:'In einer Besprechung diskutiert das Team eines Museums über den Empfang von Schulgruppen. Sarah stellt die Ergebnisse eines Fragebogens vor: Lehrkräfte wünschen sich vor dem Besuch klarere Informationen. Marc schlägt vor, zwei Wochen vorher ein Dokument zu senden, weist aber darauf hin, dass das Team die Übersetzungskosten noch nicht kennt. Die Leiterin stimmt zu, das Dokument in zwei Sprachen mit drei Schulen zu testen. Sarah erstellt am Montag eine erste Version, und Marc fragt eine Übersetzerin nach einem Kostenvoranschlag. Danach entscheidet die Gruppe, ob der Test erweitert werden soll. Das Protokoll nennt Zuständigkeiten und Fristen, stellt die Erweiterung aber nicht als bereits getroffene Entscheidung dar.',
es:'En una reunión, el equipo de un museo habla de la atención a grupos escolares. Sara presenta los resultados de un cuestionario: los docentes piden información más clara antes de la visita. Marc propone enviar un documento con dos semanas de antelación, pero recuerda que el equipo todavía no conoce el coste de traducción. La responsable acepta probar el documento en dos idiomas con tres escuelas. Sara preparará una primera versión el lunes y Marc pedirá un presupuesto a una traductora. Después el grupo decidirá si amplía la prueba. El acta indica responsables y plazos, pero no presenta la ampliación como una decisión ya tomada.'},
questions:[q('معلمان چه خواسته‌ای مطرح کرده‌اند؟',['اطلاعات روشن‌تر پیش از بازدید','لغو بازدیدهای مدرسه','افزایش قیمت بلیت'],0,'آنها اطلاعات روشن‌تری پیش از بازدید می‌خواهند.',{fr:'des informations plus claires avant leur visite',de:'vor dem Besuch klarere Informationen',es:'información más clara antes de la visita'}),q('در آزمایش اولیه سند با چند مدرسه بررسی می‌شود؟',['یک مدرسه','سه مدرسه','ده مدرسه'],1,'آزمایش با سه مدرسه انجام می‌شود.',{fr:'en deux langues avec trois écoles',de:'in zwei Sprachen mit drei Schulen',es:'en dos idiomas con tres escuelas'}),q('تصمیم دربارهٔ گسترش آزمایش در چه وضعیتی است؟',['قبلاً قطعی شده','ممنوع شده است','پس از آزمایش بررسی می‌شود'],2,'گروه بعداً دربارهٔ گسترش تصمیم می‌گیرد.',{fr:'décidera ensuite s’il faut étendre le test',de:'entscheidet die Gruppe, ob der Test erweitert werden soll',es:'Después el grupo decidirá si amplía la prueba'})],
notes:{fr:n('در جلسه نظر را با دلیل مطرح کنید و در صورت‌جلسه تصمیم قطعی را از پیشنهاد و موضوع حل‌نشده جدا نگه دارید.','Nous proposons d’envoyer le document à l’avance.','Le groupe décidera après le test s’il faut l’étendre.','اولی پیشنهاد و دومی تصمیمی است که هنوز در آینده گرفته می‌شود.',[['présenter les résultats','ارائهٔ نتایج'],['demander un devis','درخواست برآورد'],['fixer un délai','تعیین مهلت']]),de:n('در صورت‌جلسه پیشنهاد، تصمیم و کار حل‌نشده را متمایز کنید؛ فعل sollen می‌تواند وظیفه یا تصمیم پیشنهادی را گزارش کند.','Wir schlagen vor, das Dokument frühzeitig zu senden.','Nach dem Test entscheidet die Gruppe über eine Erweiterung.','اولی پیشنهاد و دومی تصمیمی است که هنوز گرفته نشده است.',[['Ergebnisse vorstellen','ارائهٔ نتایج'],['einen Kostenvoranschlag anfragen','درخواست برآورد'],['eine Frist festlegen','تعیین مهلت']]),es:n('در جلسه پیشنهاد را با دلیل و در صورت‌جلسه تصمیم، مسئول و مهلت را ثبت کنید؛ احتمال آینده را تصمیم قطعی معرفی نکنید.','Proponemos enviar el documento con antelación.','El grupo decidirá después de la prueba si la amplía.','اولی پیشنهاد و دومی تصمیمی است که هنوز گرفته نشده است.',[['presentar resultados','ارائهٔ نتایج'],['pedir un presupuesto','درخواست برآورد'],['fijar un plazo','تعیین مهلت']])},
speaking:'در جلسه پیشنهاد ارسال راهنما را مطرح کنید، محدودیت هزینه را بگویید و از اعضا دربارهٔ آزمایش نظر بخواهید.',writing:'صورت‌جلسه‌ای بنویسید که درخواست معلمان، تصمیم آزمایشی، مسئولان و موضوع حل‌نشده را مشخص کند.',steps:['هدف و نتیجهٔ پرسش‌نامه را بیان کنید.','تصمیم آزمایشی را با تعداد و زبان‌ها بنویسید.','مسئولان و مهلت را مشخص کنید.','تصمیم آینده و هزینهٔ نامعلوم را جدا نگه دارید.'],model:{fr:'L’équipe a examiné les demandes des enseignants concernant les informations avant la visite. Elle a accepté de tester un document en deux langues avec trois écoles. Sarah préparera une première version lundi et Marc demandera un devis de traduction. Le coût n’est pas encore connu. Après le test, le groupe décidera s’il souhaite l’étendre.',de:'Das Team hat die Wünsche der Lehrkräfte nach klareren Informationen vor dem Besuch besprochen. Es hat beschlossen, ein Dokument in zwei Sprachen mit drei Schulen zu testen. Sarah erstellt am Montag eine erste Version und Marc fragt nach einem Übersetzungskostenvoranschlag. Die Kosten sind noch nicht bekannt. Nach dem Test entscheidet die Gruppe über eine mögliche Erweiterung.',es:'El equipo examinó la petición de los docentes de recibir información más clara antes de la visita. Acordó probar un documento en dos idiomas con tres escuelas. Sara preparará una primera versión el lunes y Marc pedirá un presupuesto de traducción. El coste aún no se conoce. Después de la prueba, el grupo decidirá si la amplía.'}},
{id:'b2-work-conflict',level:'b2',section:'survival',number:10,title:'حل تعارض در تقسیم کار',passage:{
fr:'Dans une équipe, Emma et Rachid ne s’accordent pas sur la répartition des permanences du soir. Emma explique qu’elle a assuré trois permanences ce mois-ci et qu’elle ne peut pas modifier son horaire familial à court terme. Rachid répond qu’il a pris des tâches supplémentaires le matin et qu’il souhaite aussi une répartition équitable. Leur responsable leur demande d’abord de préciser leurs contraintes plutôt que de chercher un responsable du problème. Ils consultent le planning et proposent un échange de permanence la semaine suivante, sous réserve de trouver une personne pour couvrir une heure. Ils conviennent de vérifier cette possibilité vendredi et de réexaminer le planning mensuel ensemble.',
de:'In einem Team sind Emma und Rachid über die Verteilung der Abenddienste uneinig. Emma erklärt, dass sie diesen Monat drei Abenddienste übernommen hat und ihren Familienplan kurzfristig nicht ändern kann. Rachid antwortet, dass er morgens zusätzliche Aufgaben übernommen hat und ebenfalls eine faire Verteilung möchte. Ihre Leiterin bittet beide zunächst, ihre Einschränkungen zu erläutern, statt nach einer schuldigen Person zu suchen. Sie sehen sich den Dienstplan an und schlagen für die folgende Woche einen Tausch vor, sofern jemand eine Stunde übernehmen kann. Sie vereinbaren, diese Möglichkeit am Freitag zu prüfen und den Monatsplan gemeinsam erneut zu besprechen.',
es:'En un equipo, Emma y Rachid no están de acuerdo sobre la distribución de los turnos de tarde. Emma explica que ha cubierto tres turnos este mes y que no puede cambiar su horario familiar con poca antelación. Rachid responde que ha asumido tareas adicionales por la mañana y que también desea un reparto justo. Su responsable les pide primero que aclaren sus limitaciones en lugar de buscar a una persona culpable. Revisan el calendario y proponen intercambiar un turno la semana siguiente, siempre que alguien pueda cubrir una hora. Acuerdan comprobar esa posibilidad el viernes y volver a revisar juntos el calendario mensual.'},
questions:[q('دیدگاه اما دربارهٔ نوبت‌های عصر چیست؟',['سه نوبت پوشش داده و تغییر فوری برایش دشوار است','هیچ نوبتی نگرفته','می‌خواهد همهٔ نوبت‌ها را حذف کند'],0,'او سه نوبت را پوشش داده و محدودیت خانوادگی دارد.',{fr:'trois permanences ce mois-ci',de:'diesen Monat drei Abenddienste übernommen',es:'ha cubierto tres turnos este mes'}),q('مسئول در ابتدا چه روشی می‌خواهد؟',['پیدا کردن مقصر','روشن کردن محدودیت‌های دو طرف','لغو فوری برنامه'],1,'مسئول از آنها می‌خواهد محدودیت‌ها را توضیح دهند.',{fr:'préciser leurs contraintes plutôt que de chercher un responsable',de:'ihre Einschränkungen zu erläutern, statt nach einer schuldigen Person zu suchen',es:'aclaren sus limitaciones en lugar de buscar a una persona culpable'}),q('پیشنهاد تعویض به چه شرطی وابسته است؟',['افزایش فوری بودجه','لغو همهٔ نوبت‌ها','پیدا شدن فردی برای پوشش یک ساعت'],2,'تعویض وابسته به پوشش یک ساعت است.',{fr:'sous réserve de trouver une personne pour couvrir une heure',de:'sofern jemand eine Stunde übernehmen kann',es:'siempre que alguien pueda cubrir una hora'})],
notes:{fr:n('در حل تعارض، دیدگاه هر فرد را بدون سرزنش بازگو کنید و پیشنهاد را با «sous réserve de» مشروط سازید.','Je comprends que ton horaire est difficile à modifier.','Nous pourrions échanger, sous réserve de couvrir une heure.','اولی پذیرش محدودیت و دومی پیشنهاد مشروط است.',[['répartir les permanences','تقسیم نوبت‌ها'],['préciser une contrainte','روشن کردن محدودیت'],['échanger une permanence','تعویض نوبت']]),de:n('برای حل تعارض محدودیت هر دو طرف را روشن و پیشنهاد را با «sofern» مشروط کنید؛ فعل در پایان بند وابسته قرار می‌گیرد.','Ich verstehe, dass du deinen Familienplan nicht kurzfristig ändern kannst.','Wir könnten tauschen, sofern jemand eine Stunde übernimmt.','اولی بازگویی محدودیت و دومی پیشنهاد مشروط است.',[['Dienste verteilen','تقسیم نوبت‌ها'],['eine Einschränkung erläutern','روشن کردن محدودیت'],['einen Dienst tauschen','تعویض نوبت']]),es:n('برای حل اختلاف، مواضع را بدون سرزنش بازگو کنید؛ «siempre que» شرط پیشنهاد را با subjuntivo معرفی می‌کند.','Entiendo que no puedes cambiar tu horario familiar con poca antelación.','Podríamos intercambiar el turno siempre que alguien cubra una hora.','اولی بازگویی محدودیت و دومی پیشنهاد مشروط است.',[['distribuir los turnos','تقسیم نوبت‌ها'],['aclarar una limitación','روشن کردن محدودیت'],['intercambiar un turno','تعویض نوبت']])},
speaking:'در نقش میانجی محدودیت دو همکار را بازگو و یک پیشنهاد مشروط و گام پیگیری ارائه کنید.',writing:'پیامی برای دو همکار بنویسید که دیدگاه‌ها، شرط تعویض و زمان بررسی بعدی را بی‌طرفانه ثبت کند.',steps:['نگرانی هر دو نفر را جدا بنویسید.','از برچسب و سرزنش شخصی پرهیز کنید.','پیشنهاد و شرط لازم را بیان کنید.','زمان پیگیری و بازبینی را ذکر کنید.'],model:{fr:'Emma a assuré trois permanences et ne peut pas modifier rapidement son horaire familial. Rachid a pris des tâches supplémentaires le matin et souhaite aussi une répartition équitable. Nous proposons un échange la semaine prochaine, sous réserve de trouver quelqu’un pour couvrir une heure. Vérifions cette possibilité vendredi et revoyons ensemble le planning du mois.',de:'Emma hat drei Abenddienste übernommen und kann ihren Familienplan kurzfristig nicht ändern. Rachid hat morgens zusätzliche Aufgaben übernommen und wünscht sich ebenfalls eine faire Verteilung. Wir schlagen für nächste Woche einen Tausch vor, sofern jemand eine Stunde übernehmen kann. Wir prüfen das am Freitag und besprechen den Monatsplan danach gemeinsam.',es:'Emma ha cubierto tres turnos y no puede cambiar su horario familiar con poca antelación. Rachid ha asumido tareas adicionales por la mañana y también quiere un reparto justo. Proponemos intercambiar un turno la semana siguiente, siempre que alguien cubra una hora. Comprobaremos esta posibilidad el viernes y revisaremos juntos el calendario mensual.'}},
{id:'b2-specialist-interview',level:'b2',section:'survival',number:7,title:'مصاحبهٔ تخصصی و توضیح تجربه',passage:{
fr:'Pendant un entretien pour un poste de coordination, l’employeur demande à Lina de décrire une situation difficile. Elle raconte que, dans son ancien poste, plusieurs bénévoles avaient reçu des horaires contradictoires avant un événement. Elle a d’abord vérifié les messages, puis a créé un tableau partagé indiquant les tâches et les heures confirmées. Elle a demandé à chaque responsable de vérifier ses informations. Le jour de l’événement, l’équipe a pu ouvrir à l’heure, mais Lina précise qu’elle ne peut pas attribuer ce résultat à son seul travail. Pour une prochaine fois, elle proposerait de confirmer les horaires plus tôt et de prévoir une personne de remplacement.',
de:'In einem Vorstellungsgespräch für eine Koordinationsstelle bittet der Arbeitgeber Lina, eine schwierige Situation zu beschreiben. Sie erzählt, dass in ihrer früheren Stelle mehrere Freiwillige vor einer Veranstaltung widersprüchliche Zeiten erhalten hatten. Zuerst überprüfte sie die Nachrichten und erstellte dann eine gemeinsame Tabelle mit Aufgaben und bestätigten Uhrzeiten. Sie bat jede verantwortliche Person, ihre Angaben zu prüfen. Am Tag der Veranstaltung konnte das Team pünktlich öffnen; Lina betont jedoch, dass sie dieses Ergebnis nicht allein ihrer Arbeit zuschreiben kann. Beim nächsten Mal würde sie die Zeiten früher bestätigen und eine Ersatzperson einplanen.',
es:'Durante una entrevista para un puesto de coordinación, el empleador pide a Lina que describa una situación difícil. Ella cuenta que, en su trabajo anterior, varios voluntarios habían recibido horarios contradictorios antes de un evento. Primero revisó los mensajes y después creó una tabla compartida con las tareas y las horas confirmadas. Pidió a cada responsable que comprobara sus datos. El día del evento, el equipo pudo abrir a tiempo, pero Lina aclara que no puede atribuir ese resultado solo a su trabajo. Para la próxima vez propondría confirmar los horarios antes y prever una persona de reemplazo.'},
questions:[q('مشکل اولیه چه بود؟',['زمان‌های متناقض برای داوطلبان','نبود هیچ بازدیدکننده','لغو قرارداد ساختمان'],0,'داوطلبان زمان‌های متناقض دریافت کرده بودند.',{fr:'des horaires contradictoires avant un événement',de:'widersprüchliche Zeiten erhalten',es:'horarios contradictorios antes de un evento'}),q('لینا برای روشن کردن مسئولیت‌ها چه ساخت؟',['بلیتی جدید','جدول مشترک وظایف و ساعت‌های تأییدشده','فهرست قیمت غذا'],1,'او جدولی مشترک از وظایف و ساعت‌ها تهیه کرد.',{fr:'un tableau partagé indiquant les tâches et les heures confirmées',de:'eine gemeinsame Tabelle mit Aufgaben und bestätigten Uhrzeiten',es:'una tabla compartida con las tareas y las horas confirmadas'}),q('او نتیجه را چگونه نسبت می‌دهد؟',['صرفاً به خودش','به کار یک نفر ناشناس','به کار تیمی و نه فقط خودش'],2,'او تأکید می‌کند نتیجه حاصل کار او به‌تنهایی نبود.',{fr:'ne peut pas attribuer ce résultat à son seul travail',de:'dieses Ergebnis nicht allein ihrer Arbeit zuschreiben kann',es:'no puede atribuir ese resultado solo a su trabajo'})],
notes:{fr:n('برای پاسخ مصاحبه، موقعیت، اقدام شخصی، نتیجه و آموخته را متمایز کنید؛ از نسبت دادن نتیجهٔ جمعی فقط به خود بپرهیزید.','J’ai vérifié les messages et créé un tableau partagé.','L’équipe a ouvert à l’heure, mais ce résultat était collectif.','اولی اقدام فرد و دومی نتیجهٔ گروهی و محدودیت نسبت دادن آن است.',[['vérifier les informations','بررسی اطلاعات'],['un tableau partagé','جدول مشترک'],['prévoir une personne de remplacement','در نظر گرفتن نیروی جایگزین']]),de:n('در مصاحبه مسئله، اقدام مشخص، نتیجه و درس آموخته را به ترتیب بازگو کنید و نقش تیم را دقیق نگه دارید.','Ich habe die Nachrichten geprüft und eine gemeinsame Tabelle erstellt.','Das Team konnte pünktlich öffnen; das war eine gemeinsame Leistung.','اولی اقدام فرد و دومی نتیجهٔ گروهی است.',[['Angaben prüfen','بررسی اطلاعات'],['eine gemeinsame Tabelle','جدول مشترک'],['eine Ersatzperson einplanen','در نظر گرفتن نیروی جایگزین']]),es:n('پاسخ مصاحبه را با موقعیت، اقدام، نتیجه و آموخته بسازید؛ به سهم تیم اشاره کنید و نتیجه را اغراق‌آمیز معرفی نکنید.','Revisé los mensajes y creé una tabla compartida.','El equipo pudo abrir a tiempo; fue un resultado colectivo.','اولی اقدام فرد و دومی نتیجهٔ گروهی است.',[['comprobar los datos','بررسی اطلاعات'],['una tabla compartida','جدول مشترک'],['prever una persona de reemplazo','در نظر گرفتن نیروی جایگزین']])},
speaking:'در مصاحبه‌ای فرضی یک مشکل، اقدام شخصی، نتیجهٔ مشترک و تغییری را که دفعهٔ بعد می‌دهید بیان کنید.',writing:'پاسخ مصاحبه‌ای منسجمی بنویسید که مسئولیت فردی، نقش تیم و محدودیت نتیجه را جدا کند.',steps:['وضعیت و مشکل را معرفی کنید.','اقدام خود را به ترتیب شرح دهید.','نتیجه و نقش دیگران را بیان کنید.','درس آموخته یا پیشنهاد آینده را اضافه کنید.'],model:{fr:'Dans mon ancien poste, des bénévoles avaient reçu des horaires contradictoires avant un événement. J’ai vérifié les messages et créé un tableau partagé avec les tâches et les heures confirmées. Chaque responsable a vérifié ses informations. L’équipe a ouvert à l’heure, mais ce résultat était collectif. La prochaine fois, je confirmerais les horaires plus tôt et prévoirais une personne de remplacement.',de:'In meiner früheren Stelle hatten Freiwillige vor einer Veranstaltung widersprüchliche Zeiten erhalten. Ich prüfte die Nachrichten und erstellte eine gemeinsame Tabelle mit Aufgaben und bestätigten Uhrzeiten. Jede verantwortliche Person prüfte ihre Angaben. Das Team öffnete pünktlich, aber das Ergebnis war eine gemeinsame Leistung. Beim nächsten Mal würde ich die Zeiten früher bestätigen und eine Ersatzperson einplanen.',es:'En mi trabajo anterior, varios voluntarios habían recibido horarios contradictorios antes de un evento. Revisé los mensajes y creé una tabla compartida con tareas y horas confirmadas. Cada responsable comprobó sus datos. El equipo abrió a tiempo, pero el resultado fue colectivo. La próxima vez confirmaría los horarios antes y prevería una persona de reemplazo.'}},
{id:'b1-study-goal',level:'b1',section:'survival',number:7,title:'هدف تحصیلی و مسیر شغلی',passage:{
fr:'Mariam travaille actuellement dans un café, mais elle souhaite devenir assistante dentaire. Elle a découvert ce métier lors d’une visite dans un centre de formation. Pour préparer son projet, elle a demandé les conditions d’admission et parlé à une personne qui suit déjà la formation. Celle-ci lui a expliqué que les cours ont lieu trois jours par semaine et qu’un stage est également prévu. Mariam doit encore vérifier si les horaires sont compatibles avec son travail actuel. Elle économise chaque mois pour les frais de formation et prévoit de prendre rendez-vous avec une conseillère avant la fin du mois.',
de:'Mariam arbeitet zurzeit in einem Café, möchte aber zahnmedizinische Fachangestellte werden. Sie hat diesen Beruf bei einem Besuch in einem Ausbildungszentrum kennengelernt. Um ihr Ziel vorzubereiten, hat sie nach den Aufnahmebedingungen gefragt und mit einer Person gesprochen, die die Ausbildung bereits macht. Diese hat ihr erklärt, dass der Unterricht an drei Tagen pro Woche stattfindet und auch ein Praktikum vorgesehen ist. Mariam muss noch prüfen, ob die Zeiten zu ihrer jetzigen Arbeit passen. Sie spart jeden Monat für die Ausbildungskosten und möchte vor Monatsende einen Termin mit einer Beraterin vereinbaren.',
es:'Mariam trabaja actualmente en una cafetería, pero quiere ser auxiliar dental. Conoció esta profesión durante una visita a un centro de formación. Para preparar su proyecto, preguntó por los requisitos de acceso y habló con una persona que ya cursa la formación. Esta le explicó que las clases tienen lugar tres días por semana y que también hay prácticas. Mariam todavía debe comprobar si los horarios son compatibles con su trabajo actual. Ahorra cada mes para los gastos de formación y planea pedir una cita con una asesora antes de final de mes.'},
questions:[q('هدف شغلی مریم چیست؟',['دستیار دندان‌پزشکی شدن','افتتاح کافهٔ تازه','رانندهٔ قطار شدن'],0,'او می‌خواهد دستیار دندان‌پزشکی شود.',{fr:'devenir assistante dentaire',de:'zahnmedizinische Fachangestellte werden',es:'ser auxiliar dental'}),q('دورهٔ آموزشی چند روز در هفته کلاس دارد؟',['یک روز','سه روز','هفت روز'],1,'کلاس سه روز در هفته برگزار می‌شود.',{fr:'trois jours par semaine',de:'an drei Tagen pro Woche',es:'tres días por semana'}),q('او هنوز چه چیزی را باید بررسی کند؟',['نام شهر','قیمت قهوه','سازگاری ساعت دوره با کار فعلی'],2,'سازگاری ساعت‌ها با کار فعلی هنوز بررسی نشده است.',{fr:'si les horaires sont compatibles avec son travail actuel',de:'ob die Zeiten zu ihrer jetzigen Arbeit passen',es:'si los horarios son compatibles con su trabajo actual'})],
notes:{fr:n('برای بیان هدف از souhaiter + infinitif و برای گام لازم از devoir + infinitif استفاده کنید؛ هدف را از اقدام قطعی جدا کنید.','Elle souhaite devenir assistante dentaire.','Elle doit vérifier les horaires.','اولی هدف و دومی اقدام لازم پیش از تصمیم است.',[['les conditions d’admission','شرایط پذیرش'],['faire un stage','کارآموزی کردن'],['prendre rendez-vous','گرفتن وقت']]),de:n('möchten هدف و müssen ضرورت را بیان می‌کند. دربارهٔ زمان‌های آموزشی و شرایط پذیرش سؤال مشخص بپرسید.','Sie möchte zahnmedizinische Fachangestellte werden.','Sie muss die Zeiten prüfen.','اولی هدف و دومی کار لازم است.',[['die Aufnahmebedingungen','شرایط پذیرش'],['ein Praktikum machen','کارآموزی کردن'],['einen Termin vereinbaren','گرفتن وقت']]),es:n('querer هدف و tener que ضرورت را بیان می‌کند؛ یک هدف آینده را با اطلاعات هنوز نامعلوم اشتباه نگیرید.','Quiere ser auxiliar dental.','Tiene que comprobar los horarios.','اولی هدف و دومی اقدام لازم پیش از تصمیم است.',[['los requisitos de acceso','شرایط پذیرش'],['hacer prácticas','کارآموزی کردن'],['pedir una cita','گرفتن وقت']])},
speaking:'هدف تحصیلی یا شغلی فرضی، دلیل انتخاب، دو گام آمادگی و یک اطلاعات نامعلوم را بیان کنید.',writing:'به مشاور آموزشی پیام بدهید و هدف، تجربهٔ آشنایی، محدودیت زمانی و پرسش خود را بنویسید.',steps:['هدف و دلیل را معرفی کنید.','دو گام آمادگی را توضیح دهید.','محدودیت و اطلاعات نامعلوم را بیان کنید.','درخواست وقت یا راهنمایی کنید.'],model:{fr:'Bonjour, je travaille actuellement dans un café et je souhaite devenir assistante dentaire. J’ai visité votre centre et demandé les conditions d’admission. Je voudrais vérifier si les horaires de la formation sont compatibles avec mon travail. Pourrais-je prendre rendez-vous avec une conseillère avant la fin du mois ? Merci de votre aide.',de:'Guten Tag, ich arbeite zurzeit in einem Café und möchte zahnmedizinische Fachangestellte werden. Ich habe Ihr Zentrum besucht und nach den Aufnahmebedingungen gefragt. Nun möchte ich prüfen, ob die Ausbildungszeiten zu meiner Arbeit passen. Kann ich vor Monatsende einen Termin mit einer Beraterin vereinbaren? Vielen Dank für Ihre Hilfe.',es:'Buenos días, actualmente trabajo en una cafetería y quiero ser auxiliar dental. He visitado su centro y preguntado por los requisitos de acceso. Quisiera comprobar si los horarios de la formación son compatibles con mi trabajo. ¿Podría pedir una cita con una asesora antes de final de mes? Muchas gracias por su ayuda.'}},
{id:'b1-disagreement',level:'b1',section:'survival',number:12,title:'اختلاف‌نظر دربارهٔ برنامهٔ گروه',passage:{
fr:'Un groupe prépare une fête de quartier. Farid propose de commencer à dix-huit heures pour permettre aux familles de venir tôt. Ana préfère dix-neuf heures parce que plusieurs bénévoles travaillent jusqu’à dix-huit heures. Farid comprend cette difficulté, mais il craint que les enfants les plus jeunes partent avant le début. Ana propose alors d’ouvrir le jardin à dix-huit heures et de commencer la musique à dix-neuf heures. Le groupe accepte d’essayer cette solution si deux bénévoles peuvent préparer le jardin plus tôt. Farid et Ana vérifieront les disponibilités et confirmeront le programme vendredi.',
de:'Eine Gruppe bereitet ein Nachbarschaftsfest vor. Farid schlägt vor, um achtzehn Uhr zu beginnen, damit Familien früh kommen können. Ana bevorzugt neunzehn Uhr, weil mehrere Freiwillige bis achtzehn Uhr arbeiten. Farid versteht diese Schwierigkeit, befürchtet aber, dass die jüngsten Kinder vor dem Beginn gehen. Ana schlägt daraufhin vor, den Garten um achtzehn Uhr zu öffnen und die Musik um neunzehn Uhr zu beginnen. Die Gruppe möchte diese Lösung ausprobieren, wenn zwei Freiwillige den Garten früher vorbereiten können. Farid und Ana prüfen die Verfügbarkeit und bestätigen das Programm am Freitag.',
es:'Un grupo prepara una fiesta de barrio. Farid propone empezar a las seis para que las familias puedan venir temprano. Ana prefiere las siete porque varios voluntarios trabajan hasta las seis. Farid entiende esa dificultad, pero teme que los niños más pequeños se vayan antes de empezar. Entonces Ana propone abrir el jardín a las seis y comenzar la música a las siete. El grupo acepta probar esta solución si dos voluntarios pueden preparar el jardín antes. Farid y Ana comprobarán la disponibilidad y confirmarán el programa el viernes.'},
questions:[q('چرا فرید ساعت هجده را پیشنهاد می‌کند؟',['تا خانواده‌ها زودتر بیایند','چون همهٔ داوطلبان آزادند','چون باغ ساعت نوزده بسته می‌شود'],0,'او می‌خواهد خانواده‌ها زودتر بتوانند بیایند.',{fr:'permettre aux familles de venir tôt',de:'damit Familien früh kommen können',es:'para que las familias puedan venir temprano'}),q('آنا چرا ساعت نوزده را ترجیح می‌دهد؟',['موسیقی قبلاً آغاز شده','چند داوطلب تا هجده کار می‌کنند','همهٔ کودکان دیر می‌آیند'],1,'چند داوطلب تا ساعت هجده کار می‌کنند.',{fr:'plusieurs bénévoles travaillent jusqu’à dix-huit heures',de:'mehrere Freiwillige bis achtzehn Uhr arbeiten',es:'varios voluntarios trabajan hasta las seis'}),q('پیشنهاد توافقی به چه شرطی آزمایش می‌شود؟',['باران ببارد','همهٔ خانواده‌ها لغو کنند','دو داوطلب زودتر باغ را آماده کنند'],2,'آزمایش به امکان آماده‌سازی زودتر توسط دو داوطلب وابسته است.',{fr:'si deux bénévoles peuvent préparer le jardin plus tôt',de:'wenn zwei Freiwillige den Garten früher vorbereiten können',es:'si dos voluntarios pueden preparar el jardín antes'})],
notes:{fr:n('برای مخالفت مؤدبانه ابتدا نگرانی طرف مقابل را بپذیرید؛ سپس با «mais» نگرانی خود و با «on pourrait» جایگزین را مطرح کنید.','Je comprends ton idée, mais je crains que les enfants partent tôt.','On pourrait ouvrir le jardin avant la musique.','اولی پذیرش همراه نگرانی و دومی راه‌حل جایگزین است.',[['je comprends ta difficulté','مشکلت را درک می‌کنم'],['proposer une solution','پیشنهاد راه‌حل'],['confirmer le programme','تأیید برنامه']]),de:n('با «ich verstehe» نگرانی طرف مقابل را بازگو و با «aber» اختلاف خود را بیان کنید؛ «wir könnten» پیشنهاد را ملایم می‌کند.','Ich verstehe deinen Vorschlag, aber die Kinder könnten früh gehen.','Wir könnten den Garten vor der Musik öffnen.','اولی پذیرش همراه نگرانی و دومی راه‌حل جایگزین است.',[['ich verstehe deine Schwierigkeit','مشکلت را درک می‌کنم'],['eine Lösung vorschlagen','پیشنهاد راه‌حل'],['das Programm bestätigen','تأیید برنامه']]),es:n('ابتدا با «entiendo» دیدگاه دیگر را بپذیرید، سپس با «pero» اختلاف و با «podríamos» پیشنهاد را بیان کنید.','Entiendo tu idea, pero temo que los niños se vayan temprano.','Podríamos abrir el jardín antes de la música.','اولی پذیرش همراه نگرانی و دومی راه‌حل جایگزین است.',[['entiendo tu dificultad','مشکلت را درک می‌کنم'],['proponer una solución','پیشنهاد راه‌حل'],['confirmar el programa','تأیید برنامه']])},
speaking:'در نقش یکی از دو نفر نظر طرف مقابل را تأیید، نگرانی خود را توضیح و راه‌حل مشروط پیشنهاد کنید.',writing:'پیامی برای گروه بنویسید که دو دلیل، راه‌حل میانی، شرط و زمان تأیید را دربر گیرد.',steps:['نظر و دلیل هر دو نفر را بازگو کنید.','نگرانی را بدون سرزنش بیان کنید.','راه‌حل و شرط آن را توضیح دهید.','زمان بررسی و تأیید را اضافه کنید.'],model:{fr:'Farid propose de commencer à dix-huit heures pour les familles. Ana préfère dix-neuf heures parce que des bénévoles travaillent plus tard. Nous comprenons les deux points de vue. Nous pourrions ouvrir le jardin à dix-huit heures et commencer la musique à dix-neuf heures si deux bénévoles peuvent préparer le jardin. Nous confirmerons vendredi.',de:'Farid schlägt achtzehn Uhr für die Familien vor. Ana bevorzugt neunzehn Uhr, weil einige Freiwillige länger arbeiten. Wir verstehen beide Meinungen. Wir könnten den Garten um achtzehn Uhr öffnen und die Musik um neunzehn Uhr beginnen, wenn zwei Freiwillige den Garten früher vorbereiten können. Am Freitag bestätigen wir das Programm.',es:'Farid propone empezar a las seis para las familias. Ana prefiere las siete porque algunos voluntarios trabajan hasta tarde. Entendemos ambas opiniones. Podríamos abrir el jardín a las seis y comenzar la música a las siete si dos voluntarios pueden preparar el lugar antes. Confirmaremos el programa el viernes.'}},
{id:'b2-technology-evidence',level:'b2',section:'survival',number:14,title:'بررسی ابزار دیجیتال و دادهٔ شخصی',passage:{
fr:'Une clinique envisage d’utiliser une application pour rappeler les rendez-vous aux patients. Lors d’un essai d’un mois, cinquante personnes ont accepté de recevoir un rappel par téléphone. Le personnel a observé moins de rendez-vous manqués parmi elles, mais l’essai ne comportait pas de groupe de comparaison. Une infirmière signale aussi que certains patients partagent leur téléphone avec leur famille et ne souhaitent pas recevoir de détails médicaux. L’équipe propose donc un rappel sans information sensible et une option permettant de choisir un autre moyen de contact. Avant toute décision, la clinique demandera aux patients leur avis et examinera comment les données sont conservées.',
de:'Eine Klinik erwägt eine App, um Patientinnen und Patienten an Termine zu erinnern. Bei einem einmonatigen Versuch stimmten fünfzig Personen einer Erinnerung per Telefon zu. Das Personal beobachtete unter ihnen weniger versäumte Termine, doch der Versuch hatte keine Vergleichsgruppe. Eine Pflegekraft weist außerdem darauf hin, dass manche Menschen ihr Telefon mit der Familie teilen und keine medizinischen Einzelheiten erhalten möchten. Das Team schlägt deshalb eine Erinnerung ohne sensible Informationen und die Wahl einer anderen Kontaktmöglichkeit vor. Vor einer Entscheidung wird die Klinik die Patientinnen und Patienten um ihre Meinung bitten und prüfen, wie die Daten gespeichert werden.',
es:'Una clínica estudia usar una aplicación para recordar las citas a los pacientes. En una prueba de un mes, cincuenta personas aceptaron recibir un recordatorio por teléfono. El personal observó menos citas perdidas entre ellas, pero la prueba no tenía un grupo de comparación. Una enfermera señala además que algunos pacientes comparten el teléfono con su familia y no quieren recibir detalles médicos. Por eso el equipo propone un recordatorio sin información sensible y la opción de elegir otra forma de contacto. Antes de decidir, la clínica pedirá la opinión de los pacientes y examinará cómo se almacenan los datos.'},
questions:[q('در آزمایش چند نفر دریافت یادآور را پذیرفتند؟',['پنجاه نفر','ده نفر','پانصد نفر'],0,'پنجاه نفر دریافت یادآور را پذیرفتند.',{fr:'cinquante personnes ont accepté',de:'fünfzig Personen einer Erinnerung',es:'cincuenta personas aceptaron'}),q('محدودیت شواهد آزمایش چیست؟',['آزمایش یک سال طول کشید','گروه مقایسه وجود نداشت','همهٔ بیماران دستگاه نداشتند'],1,'نبود گروه مقایسه نتیجه‌گیری را محدود می‌کند.',{fr:'l’essai ne comportait pas de groupe de comparaison',de:'der Versuch hatte keine Vergleichsgruppe',es:'la prueba no tenía un grupo de comparación'}),q('پیشنهاد برای حفظ حریم چیست؟',['فرستادن همهٔ جزئیات به خانواده','حذف حق انتخاب','یادآور بدون اطلاعات حساس و انتخاب روش تماس'],2,'تیم پیام بدون جزئیات حساس و حق انتخاب پیشنهاد می‌کند.',{fr:'un rappel sans information sensible et une option permettant de choisir un autre moyen de contact',de:'eine Erinnerung ohne sensible Informationen und die Wahl einer anderen Kontaktmöglichkeit',es:'un recordatorio sin información sensible y la opción de elegir otra forma de contacto'})],
notes:{fr:n('هنگام بررسی فناوری، مشاهده، محدودیت مطالعه و ریسک حریم خصوصی را جدا کنید؛ همبستگی آزمایش کوچک اثبات علت نیست.','Le personnel a observé moins de rendez-vous manqués.','Cependant, il n’y avait pas de groupe de comparaison.','اولی مشاهده و دومی محدودیت نتیجه‌گیری است.',[['un rappel de rendez-vous','یادآور نوبت'],['un groupe de comparaison','گروه مقایسه'],['des données sensibles','داده‌های حساس']]),de:n('مشاهدهٔ یک آزمایش کوچک را از اثبات اثر جدا کنید؛ پیامدهای حفاظت داده و حق انتخاب مخاطب را هم بررسی کنید.','Das Personal beobachtete weniger versäumte Termine.','Der Versuch hatte jedoch keine Vergleichsgruppe.','اولی مشاهده و دومی محدودیت نتیجه‌گیری است.',[['eine Terminerinnerung','یادآور نوبت'],['eine Vergleichsgruppe','گروه مقایسه'],['sensible Daten','داده‌های حساس']]),es:n('نتیجهٔ مشاهده‌شده، محدودیت شواهد و خطر دادهٔ شخصی را جداگانه بیان کنید؛ کاهش مشاهده‌شده لزوماً اثر اثبات‌شدهٔ ابزار نیست.','El personal observó menos citas perdidas.','Sin embargo, no había un grupo de comparación.','اولی مشاهده و دومی محدودیت نتیجه‌گیری است.',[['un recordatorio de cita','یادآور نوبت'],['un grupo de comparación','گروه مقایسه'],['datos sensibles','داده‌های حساس']])},
speaking:'آزمایش ابزار را توضیح دهید، یک فایدهٔ مشاهده‌شده و محدودیت شاهد را بگویید و راهکار حفظ حریم پیشنهاد کنید.',writing:'یادداشت ارزیابی برای درمانگاه بنویسید: مشاهده، محدودیت داده، حق انتخاب و بررسی لازم پیش از تصمیم.',steps:['هدف ابزار و اندازهٔ آزمایش را بیان کنید.','مشاهده را از ادعای قطعی جدا کنید.','ریسک حریم و راهکار پیشنهادی را شرح دهید.','اطلاعات لازم برای تصمیم را مشخص کنید.'],model:{fr:'L’application pourrait aider à rappeler les rendez-vous. Pendant l’essai, le personnel a observé moins de rendez-vous manqués parmi cinquante participants, mais il n’y avait pas de groupe de comparaison. Nous ne pouvons donc pas attribuer avec certitude cette baisse à l’application. Un message sans détail médical et le choix d’un autre contact protégeraient mieux la vie privée. Il faut consulter les patients et examiner la conservation des données.',de:'Die App könnte an Termine erinnern. Während des Versuchs beobachtete das Personal unter fünfzig Teilnehmenden weniger versäumte Termine, aber es gab keine Vergleichsgruppe. Deshalb können wir den Rückgang nicht sicher der App zuschreiben. Eine Nachricht ohne medizinische Details und eine alternative Kontaktmöglichkeit würden die Privatsphäre besser schützen. Vor der Entscheidung sollten Patientenmeinungen und Datenspeicherung geprüft werden.',es:'La aplicación podría recordar las citas. Durante la prueba, el personal observó menos citas perdidas entre cincuenta participantes, pero no había un grupo de comparación. Por eso no podemos atribuir la reducción con certeza a la aplicación. Un mensaje sin detalles médicos y otra opción de contacto protegerían mejor la privacidad. Antes de decidir, conviene consultar a los pacientes y revisar el almacenamiento de datos.'}},
{id:'b2-media-analysis',level:'b2',section:'survival',number:15,title:'نقد یک گزارش رسانه‌ای',passage:{
fr:'Un article local affirme qu’un nouveau marché couvert a transformé la vie du quartier. Il cite deux commerçants qui ont vu davantage de clients depuis l’ouverture et présente des photographies d’une journée très fréquentée. L’article ne précise pourtant pas combien de commerces ont été interrogés ni si la fréquentation a changé les autres jours. Une habitante souligne que les loyers autour du marché pourraient augmenter, mais aucune donnée sur cette évolution n’est fournie. Le reportage donne une première idée du projet, sans permettre de conclure que tous les habitants en bénéficient. Avant de partager cette affirmation, le lecteur pourrait chercher des chiffres sur les loyers et interroger d’autres riverains.',
de:'Ein lokaler Artikel behauptet, eine neue Markthalle habe das Leben im Viertel verändert. Er zitiert zwei Geschäftsleute, die seit der Eröffnung mehr Kundschaft beobachtet haben, und zeigt Fotos eines besonders gut besuchten Tages. Der Artikel erklärt jedoch nicht, wie viele Geschäfte befragt wurden oder ob sich die Besucherzahlen an anderen Tagen verändert haben. Eine Anwohnerin weist darauf hin, dass die Mieten rund um den Markt steigen könnten, aber es werden keine Daten zu dieser Entwicklung genannt. Der Bericht vermittelt einen ersten Eindruck, erlaubt jedoch nicht den Schluss, dass alle Anwohner profitieren. Bevor man diese Behauptung teilt, könnte man Mietdaten suchen und weitere Menschen im Viertel befragen.',
es:'Un artículo local afirma que un nuevo mercado cubierto ha transformado la vida del barrio. Cita a dos comerciantes que han observado más clientes desde la apertura y muestra fotografías de un día muy concurrido. Sin embargo, el artículo no indica cuántos comercios fueron entrevistados ni si la afluencia cambió los demás días. Una vecina señala que los alquileres alrededor del mercado podrían aumentar, pero no se aportan datos sobre esa evolución. El reportaje ofrece una primera impresión del proyecto, sin permitir concluir que todos los vecinos se benefician. Antes de compartir esa afirmación, el lector podría buscar cifras sobre los alquileres y preguntar a más residentes.'},
questions:[{prompt:'گزارش از کدام شاهد برای تغییر کسب‌وکار استفاده می‌کند؟',choices:['نظر دو کاسب و عکس یک روز شلوغ','آمار همهٔ روزها و همهٔ مغازه‌ها','گزارش قطعی دربارهٔ اجاره'],correctIndex:0,explanation:'مطلب دو کاسب و عکس یک روز شلوغ را نقل می‌کند.',evidence:{fr:'deux commerçants qui ont vu davantage de clients',de:'zwei Geschäftsleute, die seit der Eröffnung mehr Kundschaft beobachtet haben',es:'dos comerciantes que han observado más clientes'}},{prompt:'چه چیزی دربارهٔ نمونه روشن نیست؟',choices:['نام روز افتتاح','تعداد کسبهٔ مصاحبه‌شده و مراجعه در روزهای دیگر','وجود محله'],correctIndex:1,explanation:'تعداد کسبهٔ مصاحبه‌شده و وضعیت روزهای دیگر مشخص نیست.',evidence:{fr:'combien de commerces ont été interrogés',de:'wie viele Geschäfte befragt wurden',es:'cuántos comercios fueron entrevistados'}},{prompt:'برای بررسی نگرانی دربارهٔ اجاره چه اقدامی پیشنهاد می‌شود؟',choices:['فرض افزایش قطعی','نادیده گرفتن ساکنان','جست‌وجوی دادهٔ اجاره و پرسش از ساکنان بیشتر'],correctIndex:2,explanation:'برای بررسی به دادهٔ اجاره و دیدگاه ساکنان بیشتر نیاز است.',evidence:{fr:'chercher des chiffres sur les loyers et interroger d’autres riverains',de:'Mietdaten suchen und weitere Menschen im Viertel befragen',es:'buscar cifras sobre los alquileres y preguntar a más residentes'}}],
notes:{fr:n('در نقد رسانه‌ای ادعای نویسنده، شاهد، محدودیت نمونه و دیدگاه غایب را تفکیک کنید؛ از ادعای قطعی بدون شاهد پرهیز کنید.','L’article affirme que le marché a transformé le quartier.','Cependant, les données sur les loyers ne sont pas fournies.','اولی ادعای منبع و دومی محدودیت اطلاعات است.',[['citer des témoignages','نقل شهادت‌ها'],['une journée fréquentée','روز شلوغ'],['des données sur les loyers','داده‌های اجاره']]),de:n('در تحلیل رسانه‌ای ادعای منبع و ارزیابی خود را جدا کنید؛ «jedoch» محدودیت شواهد را معرفی می‌کند.','Der Artikel behauptet, dass der Markt das Viertel verändert hat.','Daten über die Mieten fehlen jedoch.','اولی ادعای منبع و دومی محدودیت اطلاعات است.',[['Aussagen zitieren','نقل شهادت‌ها'],['ein gut besuchter Tag','روز شلوغ'],['Daten zu den Mieten','داده‌های اجاره']]),es:n('ادعای رسانه، شاهد و محدودیت آن را از نظر شخصی جدا کنید؛ «sin embargo» محدودیت را روشن می‌کند.','El artículo afirma que el mercado transformó el barrio.','Sin embargo, faltan datos sobre los alquileres.','اولی ادعای منبع و دومی محدودیت اطلاعات است.',[['citar testimonios','نقل شهادت‌ها'],['un día concurrido','روز شلوغ'],['datos sobre los alquileres','داده‌های اجاره']])},
speaking:'ادعای گزارش، شواهد ارائه‌شده، یک دیدگاه کم‌رنگ و دو دادهٔ لازم برای بررسی را توضیح دهید.',writing:'نقد کوتاهی بنویسید که خلاصهٔ ادعا، کیفیت شاهد، محدودیت و اقدام برای بررسی بیشتر را از هم جدا کند.',steps:['ادعای منبع و شاهد آن را خلاصه کنید.','محدودیت نمونه و روزهای دیگر را توضیح دهید.','نگرانی دربارهٔ اجاره را به گوینده نسبت دهید.','داده‌های لازم برای بررسی را مشخص کنید.'],model:{fr:'L’article affirme que le marché a transformé le quartier et cite deux commerçants ainsi que des images d’une journée fréquentée. Ces exemples donnent un premier aperçu, mais le nombre de commerces interrogés et les chiffres des autres jours ne sont pas précisés. Une habitante craint une hausse des loyers sans donnée fournie. Il faudrait consulter les loyers et d’autres riverains avant de généraliser.',de:'Der Artikel behauptet, der Markt habe das Viertel verändert, und nennt zwei Geschäftsleute sowie Bilder eines gut besuchten Tages. Diese Beispiele geben einen ersten Eindruck, aber die Zahl der befragten Geschäfte und Daten zu anderen Tagen fehlen. Eine Anwohnerin befürchtet steigende Mieten, ohne dass Daten genannt werden. Vor einer Verallgemeinerung sollten Mietdaten und weitere Stimmen geprüft werden.',es:'El artículo afirma que el mercado transformó el barrio y cita a dos comerciantes junto con imágenes de un día concurrido. Estos ejemplos ofrecen una primera impresión, pero no se indican el número de comercios entrevistados ni las cifras de otros días. Una vecina teme una subida de alquileres sin datos que la confirmen. Antes de generalizar habría que consultar los alquileres y otras opiniones.'}},
];
